 "content": "from collections import deque


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            component = []
            while q:
                y, x = q.popleft()
                component.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 8 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            colored = [(y,x) for y,x in component if grid[y][x] not in (0,8)]
            if not colored:
                continue
            r0 = min(y for y,x in colored)
            r1 = max(y for y,x in colored)
            c0 = min(x for y,x in colored)
            c1 = max(x for y,x in colored)
            tile = [row[c0:c1+1] for row in grid[r0:r1+1]]
            for y,x in component:
                out[y][x] = tile[(y-r0) % len(tile)][(x-c0) % len(tile[0])]
    return out


